#!/usr/bin/env node
import {
	cp,
	mkdtemp,
	mkdir,
	readFile,
	readdir,
	rm,
	stat,
	writeFile,
} from "node:fs/promises";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { spawn } from "node:child_process";
import { createRequire } from "node:module";
import { fixOpenAPISpec, validateOpenAPISpec } from "./openapi-spec.js";

const require = createRequire(import.meta.url);
const repositoryRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const clientRoot = resolve(repositoryRoot, "packages/hevy-client");
const generatedRelative = "src/generated";
const generatedRoot = resolve(clientRoot, generatedRelative);
const curatedBarrels = ["src/types.ts", "src/schemas.ts"];
const DEFAULT_COMMAND_TIMEOUT_MS = 120_000;
const DEFAULT_COMMAND_KILL_SIGNAL = "SIGTERM";
const SIGKILL_GRACE_PERIOD_MS = 2_000;

async function collectFiles(directory) {
	try {
		const entries = await readdir(directory, { withFileTypes: true });
		const files = [];
		for (const entry of entries) {
			const path = join(directory, entry.name);
			if (entry.isDirectory()) files.push(...(await collectFiles(path)));
			else files.push(path);
		}
		return files;
	} catch (error) {
		if (error?.code === "ENOENT") return [];
		throw error;
	}
}

function relativePath(root, path) {
	return relative(root, path).replaceAll("\\", "/");
}

export function isNodeModulesPath(path) {
	return path.split(/[\\/]+/).includes("node_modules");
}

/**
 * Compare two generated output trees without mutating either tree.
 *
 * The result is intentionally a list rather than a boolean so CI output
 * identifies the exact generated file that needs review.
 */
export async function compareDirectoryTrees(expectedRoot, actualRoot) {
	const expectedFiles = new Map(
		(await collectFiles(expectedRoot)).map((path) => [
			relativePath(expectedRoot, path),
			path,
		]),
	);
	const actualFiles = new Map(
		(await collectFiles(actualRoot)).map((path) => [
			relativePath(actualRoot, path),
			path,
		]),
	);
	const differences = [];
	const paths = new Set([...expectedFiles.keys(), ...actualFiles.keys()]);

	for (const path of [...paths].sort((left, right) =>
		left.localeCompare(right),
	)) {
		const expectedPath = expectedFiles.get(path);
		const actualPath = actualFiles.get(path);
		if (!expectedPath) {
			differences.push(`unexpected generated file: ${path}`);
			continue;
		}
		if (!actualPath) {
			differences.push(`missing generated file: ${path}`);
			continue;
		}

		const [expected, actual] = await Promise.all([
			readFile(expectedPath),
			readFile(actualPath),
		]);
		if (!expected.equals(actual)) {
			differences.push(`generated file differs: ${path}`);
		}
	}

	return differences;
}

/**
 * Return every file under a repository-root `src` directory. The repository
 * intentionally has no runtime root source tree; a non-empty result means a
 * generator escaped its package output closure.
 */
export async function findForbiddenRootSourceFiles(root) {
	const sourceRoot = resolve(root, "src");
	try {
		const sourceStats = await stat(sourceRoot);
		if (!sourceStats.isDirectory()) return ["src"];
	} catch (error) {
		if (error?.code === "ENOENT") return [];
		throw error;
	}

	const files = await collectFiles(sourceRoot);
	return files.length > 0
		? files.map((path) => relativePath(root, path)).sort()
		: ["src"];
}

function generatedTargetCandidates(specifier) {
	const target = specifier.slice("./generated/".length);
	if (target.includes("..")) return [];
	const candidates = [target];
	if (target.endsWith(".js")) {
		candidates.push(target.slice(0, -3) + ".ts");
		candidates.push(target.slice(0, -3) + ".json");
	}
	return candidates;
}

/**
 * Ensure curated public barrels only reference generated files that exist.
 * This keeps an upstream endpoint/schema change from silently leaving a
 * broken package API after regeneration.
 */
export async function findCuratedBarrelDrift(packageRoot) {
	const generatedDirectory = resolve(packageRoot, generatedRelative);
	const failures = [];
	const importPattern = /from\s+["'](\.\/generated\/[^"']+)["']/g;

	for (const barrel of curatedBarrels) {
		const barrelPath = resolve(packageRoot, barrel);
		let source;
		try {
			source = await readFile(barrelPath, "utf8");
		} catch (error) {
			if (error?.code === "ENOENT") {
				failures.push(`missing curated barrel: ${barrel}`);
				continue;
			}
			throw error;
		}

		for (const match of source.matchAll(importPattern)) {
			const specifier = match[1];
			const candidates = generatedTargetCandidates(specifier);
			let targetExists = false;
			for (const candidate of candidates) {
				try {
					await stat(resolve(generatedDirectory, candidate));
					targetExists = true;
					break;
				} catch {
					// Try the next extension candidate.
				}
			}
			if (!targetExists) {
				failures.push(`${barrel}: missing generated target ${specifier}`);
			}
		}
	}

	try {
		const tsc = await resolvePackageExecutable("typescript", "tsc");
		await runCommand(
			tsc.command,
			[...tsc.args, "--noEmit", "--pretty", "false", "-p", "./tsconfig.json"],
			packageRoot,
		);
	} catch (error) {
		failures.push(
			`curated barrel TypeScript check failed: ${
				error instanceof Error ? error.message : String(error)
			}`,
		);
	}

	return failures;
}

/**
 * Resolve a package's JavaScript bin entry and invoke it through Node. Calling
 * the bin entry directly avoids npm's platform-specific `.cmd`/shell shims
 * without ever interpolating arguments into a shell command.
 */
export async function resolvePackageExecutable(packageName, binName) {
	let packageJsonPath;
	try {
		packageJsonPath = require.resolve(`${packageName}/package.json`);
	} catch (error) {
		throw new Error(
			`Unable to resolve ${packageName} package metadata: ${
				error instanceof Error ? error.message : String(error)
			}`,
			{ cause: error },
		);
	}

	let packageJson;
	try {
		packageJson = JSON.parse(await readFile(packageJsonPath, "utf8"));
	} catch (error) {
		throw new Error(
			`Unable to read ${packageName} package metadata: ${
				error instanceof Error ? error.message : String(error)
			}`,
			{ cause: error },
		);
	}
	const packageBin = packageJson.bin;
	const binary =
		typeof packageBin === "string"
			? packageBin
			: (packageBin?.[binName] ?? packageBin?.[packageName]);

	if (typeof binary !== "string" || binary.length === 0) {
		throw new Error(
			`Package ${packageName} does not declare a ${binName} executable`,
		);
	}

	return {
		command: process.execPath,
		args: [resolve(dirname(packageJsonPath), binary)],
	};
}

function formatCommand(command, args) {
	return [command, ...args]
		.map((part) => JSON.stringify(String(part)))
		.join(" ");
}

export function runCommand(
	command,
	args,
	cwd,
	{
		timeout = DEFAULT_COMMAND_TIMEOUT_MS,
		killSignal = DEFAULT_COMMAND_KILL_SIGNAL,
	} = {},
) {
	const commandTimeout =
		Number.isFinite(timeout) && timeout > 0
			? Math.floor(timeout)
			: DEFAULT_COMMAND_TIMEOUT_MS;
	const displayCommand = formatCommand(command, args);

	return new Promise((resolvePromise, reject) => {
		let output = "";
		let timedOut = false;
		let settled = false;
		let timeoutHandle;
		let gracePeriodHandle;

		const finish = (callback) => {
			if (settled) return;
			settled = true;
			if (timeoutHandle) clearTimeout(timeoutHandle);
			if (gracePeriodHandle) clearTimeout(gracePeriodHandle);
			callback();
		};
		const rejectWithMessage = (status, cause) => {
			finish(() =>
				reject(
					new Error(
						[`${displayCommand} failed: ${status}`, output.trim()]
							.filter(Boolean)
							.join("\n"),
						{ cause },
					),
				),
			);
		};

		let child;
		try {
			child = spawn(command, args, {
				cwd,
				stdio: ["ignore", "pipe", "pipe"],
				shell: false,
				timeout: commandTimeout,
				killSignal,
			});
		} catch (error) {
			rejectWithMessage(
				`could not start: ${error instanceof Error ? error.message : String(error)}`,
				error,
			);
			return;
		}

		timeoutHandle = setTimeout(
			() => {
				if (child.exitCode === null && child.signalCode === null) {
					timedOut = true;
					child.kill(killSignal);

					if (killSignal !== "SIGKILL") {
						gracePeriodHandle = setTimeout(() => {
							if (child.exitCode === null && child.signalCode === null) {
								child.kill("SIGKILL");
							}
						}, SIGKILL_GRACE_PERIOD_MS);
					}
				}
			},
			Math.max(1, commandTimeout - 1),
		);
		child.stdout.on("data", (chunk) => {
			output += chunk;
		});
		child.stderr.on("data", (chunk) => {
			output += chunk;
		});
		child.once("error", (error) => {
			const code = error?.code ? ` (${error.code})` : "";
			rejectWithMessage(`could not start${code}: ${error.message}`, error);
		});
		child.once("close", (code, signal) => {
			if (timedOut) {
				rejectWithMessage(
					`timed out after ${commandTimeout}ms; sent ${String(killSignal)}`,
				);
				return;
			}
			if (code === 0) {
				finish(resolvePromise);
				return;
			}
			rejectWithMessage(
				signal ? `terminated by signal ${signal}` : `exited with code ${code}`,
			);
		});
	});
}

async function readNormalizedSpec() {
	const specPath = resolve(repositoryRoot, "openapi-spec.json");
	const source = JSON.parse(await readFile(specPath, "utf8"));
	const normalized = fixOpenAPISpec(source);
	validateOpenAPISpec(normalized);
	return {
		normalized,
		normalizationDrift: JSON.stringify(source) !== JSON.stringify(normalized),
	};
}

async function createFixtureRepository(normalizedSpec) {
	const fixtureParent = resolve(repositoryRoot, "node_modules/.cache");
	await mkdir(fixtureParent, { recursive: true });
	const root = await mkdtemp(join(fixtureParent, "generated-client-check-"));
	try {
		const fixtureClient = resolve(root, "packages/hevy-client");
		await cp(clientRoot, fixtureClient, {
			recursive: true,
			filter: (path) => !isNodeModulesPath(path),
		});
		await rm(resolve(fixtureClient, generatedRelative), {
			recursive: true,
			force: true,
		});
		await cp(
			resolve(repositoryRoot, "tsconfig.base.json"),
			resolve(root, "tsconfig.base.json"),
		);
		await writeFile(
			resolve(root, "openapi-spec.json"),
			JSON.stringify(normalizedSpec, null, "\t"),
		);
		return { root, client: fixtureClient };
	} catch (error) {
		await rm(root, { recursive: true, force: true });
		throw error;
	}
}

/**
 * Regenerate the checked contract in a temporary repository copy. Running
 * Kubb with the checked-in config is important: a future path regression must
 * create the fixture's root `src/` tree and fail this check.
 */
export async function checkGeneratedClient() {
	const { normalized, normalizationDrift } = await readNormalizedSpec();
	let fixture;
	try {
		fixture = await createFixtureRepository(normalized);
		const kubb = await resolvePackageExecutable("@kubb/cli", "kubb");
		const prettier = await resolvePackageExecutable("prettier", "prettier");
		await runCommand(
			kubb.command,
			[...kubb.args, "generate", "--config", "./kubb.config.ts"],
			fixture.client,
		);
		await runCommand(
			prettier.command,
			[...prettier.args, "--ignore-unknown", "--write", generatedRelative],
			fixture.client,
		);

		const failures = [];
		if (normalizationDrift) {
			failures.push(
				"checked OpenAPI spec is not normalized; run npm run openapi for a reviewed refresh",
			);
		}
		const rootSourceFiles = await findForbiddenRootSourceFiles(fixture.root);
		if (rootSourceFiles.length > 0) {
			failures.push(
				`forbidden root src creation: ${rootSourceFiles.join(", ")}`,
			);
		}
		failures.push(
			...(await compareDirectoryTrees(
				generatedRoot,
				resolve(fixture.client, generatedRelative),
			)),
		);
		failures.push(...(await findCuratedBarrelDrift(fixture.client)));

		if (failures.length > 0) {
			throw new Error(
				[
					"Generated client regeneration drift detected.",
					...failures.map((failure) => `- ${failure}`),
				].join("\n"),
			);
		}

		return { generatedFiles: (await collectFiles(generatedRoot)).length };
	} finally {
		if (fixture) {
			await rm(fixture.root, { recursive: true, force: true });
		}
	}
}

if (
	process.argv[1] &&
	fileURLToPath(import.meta.url) === resolve(process.argv[1])
) {
	try {
		const result = await checkGeneratedClient();
		console.log(
			`Generated client is up to date (${result.generatedFiles} files); no root src tree was created.`,
		);
	} catch (error) {
		console.error(error instanceof Error ? error.message : error);
		process.exitCode = 1;
	}
}

import { cp, mkdir, mkdtemp, readdir, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { resolve } from "node:path";
import { describe, expect, it } from "vitest";
import {
	compareDirectoryTrees,
	checkGeneratedClient,
	findCuratedBarrelDrift,
	findForbiddenRootSourceFiles,
	isNodeModulesPath,
	resolvePackageExecutable,
	runCommand,
} from "./check-generated-client.mjs";

const fixtureRoot = resolve(
	import.meta.dirname,
	"../tests/fixtures/generated-client",
);

// Keep the intentionally invalid sources inert for repository-wide checks.
async function materializeFixture(sourceRoot: string) {
	const targetRoot = await mkdtemp(
		resolve(tmpdir(), "hevy-generated-client-fixture-"),
	);

	async function copyTree(sourceDirectory: string, targetDirectory: string) {
		for (const entry of await readdir(sourceDirectory, {
			withFileTypes: true,
		})) {
			const sourcePath = resolve(sourceDirectory, entry.name);
			const targetName = entry.isFile()
				? entry.name.replace(/\.fixture$/, "")
				: entry.name;
			const targetPath = resolve(targetDirectory, targetName);

			if (entry.isDirectory()) {
				await mkdir(targetPath, { recursive: true });
				await copyTree(sourcePath, targetPath);
			} else {
				await cp(sourcePath, targetPath);
			}
		}
	}

	try {
		await copyTree(sourceRoot, targetRoot);
		return targetRoot;
	} catch (error) {
		await rm(targetRoot, { recursive: true, force: true });
		throw error;
	}
}

describe("generated client closure checks", () => {
	it("filters node_modules regardless of path separator", () => {
		expect(
			isNodeModulesPath("/tmp/project/node_modules/package/index.js"),
		).toBe(true);
		expect(
			isNodeModulesPath(String.raw`C:\project\node_modules\package\index.js`),
		).toBe(true);
		expect(isNodeModulesPath("/tmp/project/node_modules-copy/index.js")).toBe(
			false,
		);
	});

	it("resolves package bins through Node instead of platform shell shims", async () => {
		const executable = await resolvePackageExecutable("@kubb/cli", "kubb");

		expect(executable.command).toBe(process.execPath);
		expect(executable.args).toHaveLength(1);
		expect(executable.args[0]).toMatch(/[\\/]bin[\\/]kubb\.cjs$/);
	});

	it("reports missing package metadata and executable declarations", async () => {
		await expect(
			resolvePackageExecutable("missing-generated-client-package", "missing"),
		).rejects.toThrow(
			"Unable to resolve missing-generated-client-package package metadata",
		);
		await expect(
			resolvePackageExecutable("typescript", "missing"),
		).rejects.toThrow(
			"Package typescript does not declare a missing executable",
		);
	});

	it("reports command startup and non-zero exit failures", async () => {
		const root = await mkdtemp(
			resolve(tmpdir(), "hevy-generated-client-command-failure-"),
		);
		const script = resolve(root, "fail.mjs");
		try {
			await expect(
				runCommand(resolve(root, "missing-command"), [], root, {
					timeout: 1_000,
				}),
			).rejects.toThrow(/failed: could not start \(ENOENT\)/);

			await writeFile(
				script,
				'process.stderr.write("command failed\\n"); process.exitCode = 7;\n',
			);
			await expect(
				runCommand(process.execPath, [script], root, { timeout: 1_000 }),
			).rejects.toThrow(/failed: exited with code 7[\s\S]*command failed/);
		} finally {
			await rm(root, { recursive: true, force: true });
		}
	});

	it("reports bounded command failures with timeout and captured output", async () => {
		const root = await mkdtemp(
			resolve(tmpdir(), "hevy-generated-client-command-timeout-"),
		);
		const script = resolve(root, "sleep.mjs");
		try {
			await writeFile(
				script,
				'process.stderr.write("command started\\n"); setTimeout(() => {}, 5000);\n',
			);

			await expect(
				runCommand(process.execPath, [script], root, {
					timeout: 1_000,
					killSignal: "SIGTERM",
				}),
			).rejects.toMatchObject({
				message: expect.stringMatching(
					/failed: timed out after 1000ms; sent SIGTERM[\s\S]*command started/,
				),
			});
		} finally {
			await rm(root, { recursive: true, force: true });
		}
	});

	it("treats a timed-out child that exits cleanly after SIGTERM as a failure", async () => {
		const root = await mkdtemp(
			resolve(tmpdir(), "hevy-generated-client-command-clean-exit-"),
		);
		const script = resolve(root, "exit-on-sigterm.mjs");
		try {
			await writeFile(
				script,
				[
					'process.on("SIGTERM", () => process.exit(0));',
					'process.stderr.write("process started\\n");',
					"setInterval(() => {}, 1000);",
				].join("\n"),
			);

			await expect(
				runCommand(process.execPath, [script], root, {
					timeout: 1_000,
					killSignal: "SIGTERM",
				}),
			).rejects.toMatchObject({
				message: expect.stringMatching(
					/failed: timed out after 1000ms; sent SIGTERM[\s\S]*process started/,
				),
			});
		} finally {
			await rm(root, { recursive: true, force: true });
		}
	});

	it("forcefully terminates with SIGKILL after grace period if child ignores SIGTERM", async () => {
		const root = await mkdtemp(
			resolve(tmpdir(), "hevy-generated-client-command-sigkill-"),
		);
		const script = resolve(root, "ignore-sigterm.mjs");
		try {
			await writeFile(
				script,
				[
					'process.on("SIGTERM", () => {',
					'\tprocess.stderr.write("ignored SIGTERM\\n");',
					"});",
					'process.stderr.write("process started\\n");',
					"setInterval(() => {}, 1000);",
				].join("\n"),
			);

			await expect(
				runCommand(process.execPath, [script], root, {
					timeout: 1_000,
					killSignal: "SIGTERM",
				}),
			).rejects.toMatchObject({
				message: expect.stringMatching(
					/failed: timed out after 1000ms; sent SIGTERM[\s\S]*process started/,
				),
			});
		} finally {
			await rm(root, { recursive: true, force: true });
		}
	});

	it("uses SIGKILL directly when configured as the timeout signal", async () => {
		const root = await mkdtemp(
			resolve(tmpdir(), "hevy-generated-client-command-direct-sigkill-"),
		);
		const script = resolve(root, "sleep.mjs");
		try {
			await writeFile(script, "setInterval(() => {}, 1000);\n");

			await expect(
				runCommand(process.execPath, [script], root, {
					timeout: 1_000,
					killSignal: "SIGKILL",
				}),
			).rejects.toThrow(/failed: timed out after 1000ms; sent SIGKILL/);
		} finally {
			await rm(root, { recursive: true, force: true });
		}
	});

	it("reports a child terminated by a signal before the timeout", async () => {
		const root = await mkdtemp(
			resolve(tmpdir(), "hevy-generated-client-command-signal-"),
		);
		const script = resolve(root, "terminate.mjs");
		try {
			await writeFile(
				script,
				'setTimeout(() => process.kill(process.pid, "SIGTERM"), 50);\n',
			);

			await expect(
				runCommand(process.execPath, [script], root, { timeout: 1_000 }),
			).rejects.toThrow(/failed: terminated by signal SIGTERM/);
		} finally {
			await rm(root, { recursive: true, force: true });
		}
	});

	it("returns no differences when both comparison trees are absent", async () => {
		const root = await mkdtemp(
			resolve(tmpdir(), "hevy-generated-client-empty-trees-"),
		);
		try {
			expect(
				await compareDirectoryTrees(
					resolve(root, "expected"),
					resolve(root, "actual"),
				),
			).toEqual([]);
		} finally {
			await rm(root, { recursive: true, force: true });
		}
	});

	it("propagates non-directory comparison errors", async () => {
		const root = await mkdtemp(
			resolve(tmpdir(), "hevy-generated-client-not-directory-"),
		);
		const file = resolve(root, "not-a-directory");
		try {
			await writeFile(file, "fixture");
			await expect(compareDirectoryTrees(file, file)).rejects.toMatchObject({
				code: "ENOTDIR",
			});
		} finally {
			await rm(root, { recursive: true, force: true });
		}
	});

	it("reports stale generated output", async () => {
		const drift = await compareDirectoryTrees(
			resolve(fixtureRoot, "stale/expected"),
			resolve(fixtureRoot, "stale/actual"),
		);

		expect(drift).toEqual([
			"generated file differs: client/types/index.ts",
			"missing generated file: client/types/Routine.ts",
			"unexpected generated file: client/types/Workout.ts",
		]);
	});

	it("reports a forbidden root src tree", async () => {
		const sourceFiles = await findForbiddenRootSourceFiles(
			resolve(fixtureRoot, "forbidden-root"),
		);

		expect(sourceFiles).toEqual(["src/generated/index.ts"]);
	});

	it("handles absent, empty, and non-directory root src paths", async () => {
		const root = await mkdtemp(
			resolve(tmpdir(), "hevy-generated-client-root-src-"),
		);
		try {
			expect(await findForbiddenRootSourceFiles(root)).toEqual([]);

			await mkdir(resolve(root, "src"));
			expect(await findForbiddenRootSourceFiles(root)).toEqual(["src"]);

			await rm(resolve(root, "src"), { recursive: true, force: true });
			await writeFile(resolve(root, "src"), "fixture");
			expect(await findForbiddenRootSourceFiles(root)).toEqual(["src"]);
		} finally {
			await rm(root, { recursive: true, force: true });
		}
	});

	it("keeps the curated barrels closed over generated output", async () => {
		expect(
			await findCuratedBarrelDrift(
				resolve(import.meta.dirname, "../packages/hevy-client"),
			),
		).toEqual([]);
	});

	it("reports missing curated barrels and traversal targets", async () => {
		const root = await mkdtemp(
			resolve(tmpdir(), "hevy-generated-client-barrel-drift-"),
		);
		try {
			await mkdir(resolve(root, "src/generated"), { recursive: true });
			await writeFile(
				resolve(root, "src/types.ts"),
				'export type { Escaped } from "./generated/../escape.js";\n',
			);

			const failures = await findCuratedBarrelDrift(root);
			expect(failures).toContain("missing curated barrel: src/schemas.ts");
			expect(failures).toContain(
				"src/types.ts: missing generated target ./generated/../escape.js",
			);
		} finally {
			await rm(root, { recursive: true, force: true });
		}
	});

	it("regenerates the checked client without drift", async () => {
		const result = await checkGeneratedClient();

		expect(result.generatedFiles).toBeGreaterThan(0);
	}, 60_000);

	it("reports a missing named public export", async () => {
		const fixture = await materializeFixture(
			resolve(fixtureRoot, "stale-public-export"),
		);
		try {
			const drift = await findCuratedBarrelDrift(fixture);

			expect(drift).toHaveLength(1);
			expect(drift[0]).toMatch(
				/has no exported member ['"]MissingPublicType['"]/,
			);
			expect(drift.join("\n")).not.toContain("missing curated barrel");
		} finally {
			await rm(fixture, { recursive: true, force: true });
		}
	});
});

